P=dict(ch=7,nv=30,V=V,per=[15,15],out='/home/claude/work/gita/Gita_Chapter07.html',
 title='Knowing and Realising · Bhagavad Gītā Chapter 7 · srini.presents',
 desc='Bhagavad Gītā chapter 7, Jñāna Vijñāna Yoga, every śloka explained: the Lord’s two natures, all things strung on him like pearls on a thread, the taste in water and light in the sun, māyā and refuge, the four kinds of devotees, and “Vāsudeva is all”. All 30 ślokas in IAST, each on two pages.',
 burst='CHAPTER 7 OF 18',h1='KNOWING AND REALISING',series='BHAGAVAD GĪTĀ · CHAPTER 7 · JÑĀNA VIJÑĀNA YOGA',tag='Pearls on a thread · every śloka explained',cover=cover,
 where=[f'In {chl(6)} Kṛṣṇa taught meditation and ended: the best yogi is the one who worships me with faith.',
  'Chapter 7 begins the middle part of the Gītā, about the Lord himself. Kṛṣṇa describes his two natures, matter and life; he is the thread through all things, the taste in water and the light in the sun. Few know him; māyā veils him; but those who take refuge cross over.'],
 wtalk=("Who is Kṛṣṇa, really?","That is what chapters 7 to 12 answer. Here he starts with: I am the thread through everything."),
 fullnote=FULLNOTE,
 secs=[('KNOWING THE LORD',1),('TWO NATURES',4),('THE ESSENCE OF THINGS',8),('MĀYĀ',13),('FOUR KINDS OF DEVOTEES',16),('OTHER GODS, AND THE VEIL',20)],
 end=['<b>Knowing (7.1–3).</b> Kṛṣṇa will teach knowledge with realisation; true knowers are rare.',
  '<b>Two natures (7.4–7).</b> Matter and mind are his lower nature; life is his higher; all is strung on him like pearls on a thread.',
  '<b>The essence (7.8–12).</b> He is the taste in water, light in the sun, fragrance of earth, strength free of desire.',
  '<b>Māyā (7.13–19).</b> The guṇas delude; refuge in him crosses māyā; four kinds of devotees, the wise dearest; “Vāsudeva is all”.',
  '<b>The veil (7.20–30).</b> Other gods give limited fruit; he steadies all faith; veiled by yoga-māyā, he is known by the pure, even at death.'],
 endsub='Chapter 7 in five lines',
 next=("What's next?",f'{chl(8)}: The Imperishable. Arjuna asks what Brahman, karma and the rest mean, and what happens at death. Kṛṣṇa answers: what you think of at the end, you become.'),
 endkey='<b>all is strung on the Lord, like pearls on a thread</b>.',
 foot=FOOT(7,'Examples of the four kinds of devotees (Draupadī, Uddhava, Dhruva, Śuka) are traditional, not in the Gītā text. '))
